// Deterministic demo dataset for the AIPlat console.
//
// Every number here is synthetic. Nothing is read from a deployment, an AWS
// account or a real organization — the screenshots in the README are generated
// from this file so they can be regenerated by anyone, and so no customer data
// ever ends up in a published image.
//
// Determinism matters: the PRNG is seeded, so two runs produce byte-identical
// numbers and a screenshot refresh shows a real diff instead of noise.

const SEED = 20260901;

// mulberry32 — small, fast, seeded. Good enough for shaping demo data.
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const r2 = (v) => Number(v.toFixed(2));
const r4 = (v) => Number(v.toFixed(4));
const r6 = (v) => Number(v.toFixed(6));

