// ---------------------------------------------------------------- usage
const DAYS = 30;

// One pass builds the whole period so the totals and the series can never
// disagree — a mismatch between a card and its chart is the kind of thing that
// makes a screenshot look broken.
function buildUsage() {
  const rnd = rng(SEED);
  const labels = [];
  const series = [];
  const byReasonSeries = {
    cache: [], provider_prompt_cache: [], provider_arbitrage: [],
    semantic_cache: [], auto_cheapest: [], fallback: [], budget_degrade: [],
  };

  const totals = {
    cost: 0, requests: 0, cacheHits: 0, tokensIn: 0, tokensOut: 0, latencySum: 0,
    saved: { cache: 0, provider_prompt_cache: 0, provider_arbitrage: 0, semantic_cache: 0, auto_cheapest: 0, fallback: 0, budget_degrade: 0 },
  };

  const start = new Date();
  start.setUTCHours(0, 0, 0, 0);
  start.setUTCDate(start.getUTCDate() - (DAYS - 1));

  for (let i = 0; i < DAYS; i++) {
    const day = new Date(start);
    day.setUTCDate(start.getUTCDate() + i);
    labels.push(day.toISOString().slice(0, 10));

    // Weekdays carry more traffic than weekends; a flat line looks fake.
    const dow = day.getUTCDay();
    const weekend = dow === 0 || dow === 6;
    const base = weekend ? 420 : 1350;
    // Gentle growth across the month so the cumulative chart has a shape.
    const growth = 1 + i * 0.02;
    const requests = Math.round(base * growth * (0.85 + rnd() * 0.3));
    const cacheHits = Math.round(requests * (0.24 + rnd() * 0.1));
    const tokensIn = Math.round(requests * (780 + rnd() * 220));
    const tokensOut = Math.round(requests * (190 + rnd() * 90));
    const cost = r6((tokensIn / 1000) * 0.0016 + (tokensOut / 1000) * 0.0072);
    const latency = Math.round(620 + rnd() * 520);

    series.push({ key: labels[i], cost_usd: cost, requests });

    totals.cost = r6(totals.cost + cost);
    totals.requests += requests;
    totals.cacheHits += cacheHits;
    totals.tokensIn += tokensIn;
    totals.tokensOut += tokensOut;
    totals.latencySum += latency * requests;

    // Savings per mechanism. Cache dominates (it is the verified one), the
    // counterfactual mechanisms are deliberately smaller.
    const sv = {
      cache: r6(cost * (0.17 + rnd() * 0.05)),
      provider_prompt_cache: r6(cost * (0.05 + rnd() * 0.03)),
      provider_arbitrage: r6(cost * (0.04 + rnd() * 0.02)),
      semantic_cache: r6(cost * (0.03 + rnd() * 0.02)),
      auto_cheapest: r6(cost * (0.08 + rnd() * 0.04)),
      fallback: r6(cost * (0.01 + rnd() * 0.01)),
      budget_degrade: r6(i > 22 ? cost * (0.02 + rnd() * 0.02) : 0),
    };
    for (const k of Object.keys(sv)) {
      byReasonSeries[k].push(sv[k]);
      totals.saved[k] = r6(totals.saved[k] + sv[k]);
    }
  }

  const savedVerified = r4(totals.saved.cache + totals.saved.provider_prompt_cache + totals.saved.provider_arbitrage);
  const savedCounter = r4(totals.saved.semantic_cache + totals.saved.auto_cheapest + totals.saved.fallback + totals.saved.budget_degrade);
  const savedTotal = r4(savedVerified + savedCounter);
  const gross = totals.cost + savedTotal;

  // credit + cash is a partition of cost — the console asserts that visually.
  const credit = r4(totals.cost * 0.38);
  const cash = r4(totals.cost - credit);

  const cost = r4(totals.cost);

  return {
    // Echo the request window, as the real usage-api response does — the console never
    // reads these back, but a shape audit against the live API compares them.
    bucket: 'day',
    from: labels[0],
    to: labels[labels.length - 1],
    totals: {
      cost_usd: cost,
      requests: totals.requests,
      cache_hits: totals.cacheHits,
      tokens_in: totals.tokensIn,
      tokens_out: totals.tokensOut,
      avg_latency_ms: Math.round(totals.latencySum / totals.requests),
      saved_usd: savedTotal,
      saved_pct: r2((savedTotal / gross) * 100),
      saved_verified_usd: savedVerified,
      saved_verified_pct: r2((savedVerified / gross) * 100),
      saved_counterfactual_usd: savedCounter,
      credit_usd: credit,
      cash_usd: cash,
      list_price_pct: 71,
      cost_list_price_usd: r4(cost * 0.71),
    },
    sli: {
      eligible: Math.round(totals.requests * 0.97),
      bad: Math.round(totals.requests * 0.0016),
      availability_pct: 99.84,
    },
    series,
    by_model: [
      { key: 'claude-sonnet', cost_usd: r4(cost * 0.46) },
      { key: 'claude-sonnet-byo', cost_usd: r4(cost * 0.27) },
      { key: 'nova-lite', cost_usd: r4(cost * 0.15) },
      { key: 'llama-scout', cost_usd: r4(cost * 0.08) },
      { key: 'mixtral-selfhosted', cost_usd: r4(cost * 0.04) },
    ],
    by_feature: [
      { key: 'support-copilot', cost_usd: r4(cost * 0.34) },
      { key: 'checkout', cost_usd: r4(cost * 0.26) },
      { key: 'search', cost_usd: r4(cost * 0.19) },
      { key: 'summarize', cost_usd: r4(cost * 0.13) },
      { key: 'default', cost_usd: r4(cost * 0.08) },
    ],
    by_team: [
      { key: 'platform', cost_usd: r4(cost * 0.41) },
      { key: 'growth', cost_usd: r4(cost * 0.31) },
      { key: 'support', cost_usd: r4(cost * 0.28) },
    ],
    by_app: [
      { key: 'web', cost_usd: r4(cost * 0.38) },
      { key: 'mobile', cost_usd: r4(cost * 0.24) },
      { key: 'batch-jobs', cost_usd: r4(cost * 0.21) },
      { key: 'internal-tools', cost_usd: r4(cost * 0.17) },
    ],
    // Each row also carries the credit/cash and verified/counterfactual split and the two
    // price references (list vs contract) that the real usage-api response includes —
    // fields the console reads on this breakdown, not only on `totals`.
    by_provider: [
      {
        key: 'bedrock',
        requests: Math.round(totals.requests * 0.93),
        tokens_in: Math.round(totals.tokensIn * 0.93),
        tokens_out: Math.round(totals.tokensOut * 0.93),
        cost_usd: r4(cost * 0.96),
        saved_usd: r4(savedTotal * 0.97),
        cache_hits: Math.round(totals.cacheHits * 0.95),
        credit_usd: r4(credit * 0.96),
        cash_usd: r4(cash * 0.96),
        saved_verified_usd: r4(savedVerified * 0.97),
        saved_counterfactual_usd: r4(savedCounter * 0.97),
        cost_list_price_usd: r4(cost * 0.96 * 0.71),
        cost_contract_price_usd: 0,
      },
      {
        key: 'openai_compatible',
        requests: Math.round(totals.requests * 0.07),
        tokens_in: Math.round(totals.tokensIn * 0.07),
        tokens_out: Math.round(totals.tokensOut * 0.07),
        cost_usd: r4(cost * 0.04),
        saved_usd: r4(savedTotal * 0.03),
        cache_hits: Math.round(totals.cacheHits * 0.05),
        credit_usd: r4(credit * 0.04),
        cash_usd: r4(cash * 0.04),
        saved_verified_usd: r4(savedVerified * 0.03),
        saved_counterfactual_usd: r4(savedCounter * 0.03),
        cost_list_price_usd: r4(cost * 0.04 * 0.71),
        cost_contract_price_usd: 0,
      },
    ],
    // The two real destinations behind by_provider's two rows: BYO Bedrock in the
    // customer's own account/region, and the self-hosted openai_compatible endpoint.
    by_upstream: [
      { key: 'bedrock-us-west-2', cost_usd: r4(cost * 0.96), requests: Math.round(totals.requests * 0.93) },
      { key: 'acme-selfhosted', cost_usd: r4(cost * 0.04), requests: Math.round(totals.requests * 0.07) },
    ],
    savings_by_reason: [
      { key: 'cache', saved_usd: totals.saved.cache },
      { key: 'provider_prompt_cache', saved_usd: totals.saved.provider_prompt_cache },
      { key: 'provider_arbitrage', saved_usd: totals.saved.provider_arbitrage },
      { key: 'semantic_cache', saved_usd: totals.saved.semantic_cache },
      { key: 'auto_cheapest', saved_usd: totals.saved.auto_cheapest },
      { key: 'fallback', saved_usd: totals.saved.fallback },
      { key: 'budget_degrade', saved_usd: totals.saved.budget_degrade },
    ],
    savings_series: { labels, by_reason: byReasonSeries },
    by_swap_class: [
      { key: 'none', requests: Math.round(totals.requests * 0.78) },
      { key: 'same_model', requests: Math.round(totals.requests * 0.13) },
      { key: 'equivalent', requests: Math.round(totals.requests * 0.07) },
      { key: 'downgrade', requests: Math.round(totals.requests * 0.02) },
    ],
  };
}

export const USAGE = buildUsage();

// ---------------------------------------------------------------- records
const FEATURES = ['support-copilot', 'checkout', 'search', 'summarize', 'default'];
const MODELS = ['claude-sonnet', 'claude-sonnet-byo', 'nova-lite', 'llama-scout', 'mixtral-selfhosted'];

// A realistic log page: mostly served, a healthy slice of cache, a few swaps,
// a couple of provider errors and two guardrail blocks. Every branch of the
// Logs renderer is exercised, which is the point of a screenshot.
function buildRecords(n) {
  const rnd = rng(SEED + 7);
  const out = [];
  const now = Date.now();
  for (let i = 0; i < n; i++) {
    // Timestamps walk backwards from now — never into the future.
    const ts = new Date(now - i * 97_000 - Math.floor(rnd() * 40_000)).toISOString().replace(/\.\d+Z$/, 'Z');
    const model = MODELS[Math.floor(rnd() * MODELS.length)];
    const tokensIn = Math.round(500 + rnd() * 1800);
    const tokensOut = Math.round(120 + rnd() * 700);
    const price = PRICING[model] || { input: 0, output: 0 };
    const cost = r6((tokensIn / 1000) * price.input + (tokensOut / 1000) * price.output);
    const rec = {
      ts,
      model,
      requested_model: model,
      // requested_cost_usd is what the REQUESTED model would have cost — equal to cost_usd
      // until a swap branch below re-prices the actually-served model.
      requested_cost_usd: cost,
      served_model_id: (ROUTING[model] && ROUTING[model].model_id) || model,
      provider: ROUTING[model].provider,
      upstream: ROUTING[model].provider === 'bedrock' ? 'bedrock-' + (ROUTING[model].region || 'us-west-2') : 'acme-selfhosted',
      feature: FEATURES[Math.floor(rnd() * FEATURES.length)],
      tokens_in: tokensIn,
      tokens_out: tokensOut,
      cost_usd: cost,
      latency_ms: Math.round(180 + rnd() * 1900),
      result: 'served',
      status: 'success',
      cache_hit: false,
      swap_class: null,
      canary: false,
    };

    const dice = rnd();
    if (dice < 0.26) {
      rec.result = 'cache';
      rec.status = 'cache';
      rec.cache_hit = true;
      rec.cost_usd = 0;
      rec.latency_ms = Math.round(18 + rnd() * 60);
    } else if (dice < 0.32) {
      rec.result = 'cache';
      rec.status = 'cache';
      rec.cache_hit = true;
      rec.savings_reason = 'semantic_cache';
      rec.cost_usd = 0;
      rec.latency_ms = Math.round(40 + rnd() * 90);
    } else if (dice < 0.40) {
      // Same model reached through the customer's own account: no quality risk.
      rec.requested_model = 'claude-sonnet';
      rec.model = 'claude-sonnet-byo';
      rec.served_model_id = (ROUTING['claude-sonnet-byo'] && ROUTING['claude-sonnet-byo'].model_id) || 'claude-sonnet-byo';
      rec.swap_class = 'same_model';
      rec.savings_reason = 'provider_arbitrage';
    } else if (dice < 0.46) {
      rec.requested_model = 'claude-sonnet';
      rec.model = 'nova-lite';
      rec.served_model_id = (ROUTING['nova-lite'] && ROUTING['nova-lite'].model_id) || 'nova-lite';
      rec.swap_class = 'equivalent';
      rec.savings_reason = 'auto_cheapest';
    } else if (dice < 0.48) {
      rec.requested_model = 'claude-sonnet';
      rec.model = 'llama-scout';
      rec.served_model_id = (ROUTING['llama-scout'] && ROUTING['llama-scout'].model_id) || 'llama-scout';
      rec.swap_class = 'downgrade';
      rec.savings_reason = 'budget_degrade';
    } else if (dice < 0.505) {
      rec.result = 'error';
      rec.status = 'error';
      rec.reason = rnd() < 0.5 ? 'provider_rate_limited' : 'provider_quota_exceeded';
      rec.detail = 'upstream returned 429 after 2 retries';
      rec.cost_usd = 0;
    } else if (dice < 0.52) {
      rec.result = 'blocked';
      rec.status = 'blocked';
      rec.reason = rnd() < 0.5 ? 'secret_detected' : 'prompt_injection';
      rec.detail = 'guardrail matched before the request left the gateway';
      rec.cost_usd = 0;
    } else if (dice < 0.535) {
      rec.canary = true;
      rec.canary_route = 'nova-lite';
    }
    out.push(rec);
  }
  return out;
}

export const RECORDS = buildRecords(200);

// ---------------------------------------------------------------- alerts log
function isoAgo(hours) {
  return new Date(Date.now() - hours * 3600_000).toISOString().replace(/\.\d+Z$/, 'Z');
}

